content.content:
   DESTAQUE
   ========================================================= */
.featured {
  position: relative; margin-top: 34px;
  display: grid; grid-template-columns: minmax(0, 1.02fr) minmax(0, .98fr); gap: 0;
  border: 2px solid var(--ink); background: var(--paper-white);
  box-shadow: 8px 8px 0 rgba(16, 16, 20, .12);
}
/* o card social é uma peça desenhada em 1200×630: mostrar inteiro (contain),
   nunca recortar. O gradiente acompanha a rampa vertical do próprio card
   (topo #131b29 → base #0a0c12), então a caixa preta em volta não faz emenda. */
.featured-media {
  position: relative; border-right: 2px solid var(--ink); overflow: hidden;
  background: linear-gradient(180deg, #131b29 0%, #10141d 42%, #0d1017 62%, #0a0c12 100%);
  display: grid; place-items: center;
}
.featured-media::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background-image: var(--grain-dark); background-size: 3px 3px; opacity: .7;
}
/* fio de luz + sombra: a placa vira peça montada, e a emenda do letterbox
   passa a ler como moldura, de propósito. */
.featured-media img {
  display: block; position: relative; z-index: 1;
  width: 100%; height: auto; max-height: 100%; object-fit: contain;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .12), 0 16px 40px rgba(0, 0, 0, .55);
}
.featured-flag {
  position: absolute; top: 18px; left: -1px; z-index: 2;
  background: var(--red); color: var(--paper-white);
  font: 800 .64rem var(--sans); letter-spacing: .16em; text-transform: uppercase;
  padding: 7px 14px 6px; box-shadow: 3px 3px 0 rgba(16, 16, 20, .3);
}
.featured-body { padding: clamp(22px, 2.4vw, 34px); display: flex; flex-direction: column; }
.featured-meta { display: flex; flex-wrap: wrap; gap: 6px 10px; margin-bottom: 16px; }
.chip {
  font-family: var(--mono); font-size: .68rem; letter-spacing: .04em;
  border: 1px solid var(--edge); background: var(--paper-2); color: var(--muted);
  padding: 4px 8px; border-radius: 2px; white-space: nowrap;
}
.chip.key { border-color: var(--ink); color: var(--ink); background: transparent; font-weight: 600; }
/* .title é h2 (ordem de cabeçalhos), com escala própria — não a de h2 global */
.featured-body .title {
  font-family: var(--display); font-optical-sizing: auto; font-weight: 900;
  font-size: clamp(1.9rem, 2.9vw, 2.9rem); line-height: .96; letter-spacing: -.025em; color: var(--ink);
}
.featured-body .title em { font-style: italic; color: var(--red); }
.featured-body > p { margin: 14px 0 0; font-size: 1.02rem; line-height: 1.5; }

.scoreline { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 2px; margin: 22px 0 0; background: var(--edge); border: 1px solid var(--edge); }
.scoreline div { background: var(--paper-white); padding: 13px 12px; min-width: 0; }
.scoreline b {
  display: block; font-family: var(--display); font-optical-sizing: auto; font-weight: 900;
  font-size: clamp(1.5rem, 2.2vw, 2rem); line-height: .9; letter-spacing: -.04em; color: var(--red);
}
