cd ~/arvor/PNAD && python3 - <<'PY'
def lum(c):
    def ch(v):
        v/=255
        return v/12.92 if v<=0.03928 else ((v+0.055)/1.055)**2.4
    return .2126*ch(c[0])+.7152*ch(c[1])+.0722*ch(c[2])
def cr(a,b):
    x,y=lum(a),lum(b); return (max(x,y)+.05)/(min(x,y)+.05)
def hx(s):
    s=s.lstrip('#'); return tuple(int(s[i:i+2],16) for i in (0,2,4))
# candidates with headroom on the lightest masthead background sampled
for c in ["#8f8b80","#918d82","#979286","#9b968a","#a09b8e"]:
    print(f"{c}  on #2f231d={cr(hx(c),hx('#2f231d')):.2f}  on #101014={cr(hx(c),hx('#101014')):.2f}")
print()
for c in ["#6f6b62","#817c72","#868176","#8a857a"]:
    print(f"colophon {c} on #101014={cr(hx(c),hx('#101014')):.2f}")
print()
print("green #066f54 on #fffaf0 (ficha accent) =", round(cr(hx('#066f54'),hx('#fffaf0')),2))
print("green #066f54 on #e7ddca (stamp)        =", round(cr(hx('#066f54'),hx('#e7ddca')),2))
print("gold  #825900 on #e7ddca (stamp)        =", round(cr(hx('#825900'),hx('#e7ddca')),2))
print("gold  #825900 on #f2ebdd                =", round(cr(hx('#825900'),hx('#f2ebdd')),2))
print("orange-ink #bb550e on #fffaf0           =", round(cr(hx('#bb550e'),hx('#fffaf0')),2))
PY

